const menu=document.querySelector('#menu-toggle'),nav=document.querySelector('#main-nav');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){menu.setAttribute('aria-expanded','false');nav.classList.remove('open');menu.focus()}});
const dialog=document.querySelector('#media-dialog'),content=document.querySelector('#dialog-content'),title=document.querySelector('#dialog-title'),galleryControls=document.querySelector('#gallery-controls');
let opener=null,gallery=[],photo=0;
document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>{content.replaceChildren();document.body.style.overflow='';opener?.focus()});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function openDialog(button){opener=button;dialog.showModal();document.body.style.overflow='hidden';document.querySelector('#close-dialog').focus()}
document.querySelectorAll('[data-video]').forEach(button=>button.addEventListener('click',()=>{dialog.classList.toggle('short-video',button.dataset.short==='true');title.textContent=button.dataset.title;galleryControls.hidden=true;const frame=document.createElement('iframe');frame.src=`https://www.youtube-nocookie.com/embed/${button.dataset.video}?rel=0`;frame.title=button.dataset.title;frame.allow='accelerometer; encrypted-media; gyroscope; picture-in-picture; web-share';frame.referrerPolicy='strict-origin-when-cross-origin';frame.allowFullscreen=true;const p=document.createElement('p'),a=document.createElement('a');a.href=`https://www.youtube.com/watch?v=${button.dataset.video}`;a.textContent='Watch on YouTube ↗';p.append(a);content.replaceChildren(frame,p);openDialog(button)}));
async function showPhoto(index){photo=(index+gallery.length)%gallery.length;const item=gallery[photo];dialog.classList.remove('short-video');title.textContent=item.caption;const img=document.createElement('img');img.src=item.src;img.alt=item.alt;content.replaceChildren(img);document.querySelector('#photo-counter').textContent=`${photo+1} of ${gallery.length}`}
document.querySelectorAll('[data-gallery]').forEach(button=>button.addEventListener('click',async()=>{try{if(!gallery.length){const r=await fetch('/gallery.json');if(!r.ok)throw Error('Unavailable');gallery=await r.json()}galleryControls.hidden=false;await showPhoto(Number(button.dataset.gallery));openDialog(button)}catch{title.textContent='Photo';galleryControls.hidden=true;const img=button.querySelector('img').cloneNode();content.replaceChildren(img);openDialog(button)}}));
document.querySelector('#prev-photo').addEventListener('click',()=>showPhoto(photo-1));
document.querySelector('#next-photo').addEventListener('click',()=>showPhoto(photo+1));
dialog.addEventListener('keydown',e=>{if(!galleryControls.hidden&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();showPhoto(photo+(e.key==='ArrowLeft'?-1:1))}});
const filters=[...document.querySelectorAll('[data-filter]')],sort=document.querySelector('#clip-sort');
let category='All Games';
function filterClips(){let count=0;document.querySelectorAll('#clip-grid .video-card').forEach(card=>{const show=(category==='All Games'||card.dataset.game===category)&&(sort.value==='all'||card.dataset.popular==='true');card.hidden=!show;if(show)count++});document.querySelector('#clip-count').textContent=`${count} ${count===1?'video':'videos'} to explore`;document.querySelector('#clip-empty').hidden=count>0;filters.forEach(b=>{const active=b.dataset.filter===category;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
filters.forEach(button=>button.addEventListener('click',()=>{category=button.dataset.filter;filterClips()}));
if(sort){sort.addEventListener('change',filterClips);const requested=new URLSearchParams(location.search).get('game');if(filters.some(b=>b.dataset.filter===requested))category=requested;filterClips()}
document.querySelector('#copy-discord')?.addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText('quadmann');status.textContent='Copied! Add quadmann on Discord.'}catch{status.textContent='Select and copy this username: quadmann'}});
